','N','0','admin','2026-08-21 09:12:05','',NULL,'删除操作'),(22,4,'授权','4','sys_oper_type','','primary','N','0','admin','2026-08-21 09:12:05','',NULL,'授权操作'),(23,5,'导出','5','sys_oper_type','','warning','N','0','admin','2026-08-21 09:12:05','',NULL,'导出操作'),(24,6,'导入','6','sys_oper_type','','warning','N','0','admin','2026-08-21 09:12:05','',NULL,'导入操作'),(25,7,'强退','7','sys_oper_type','','danger','N','0','admin','2026-08-21 09:12:05','',NULL,'强退操作'),(26,8,'生成代码','8','sys_oper_type','','warning','N','0','admin','2026-08-21 09:12:05','',NULL,'生成操作'),(27,9,'清空数据','9','sys_oper_type','','danger','N','0','admin','2026-08-21 09:12:05','',NULL,'清空操作'),(28,1,'成功','0','sys_common_status','','primary','N','0','admin','2026-08-21 09:12:05','',NULL,'正常状态'),(29,2,'失败','1','sys_common_status','','danger','N','0','admin','2026-08-21 09:12:05','',NULL,'停用状态'),(100,1,'AI 内容创作','1','book_type',NULL,'primary','N','0','admin','2026-08-21 09:12:06','',NULL,NULL),(101,2,'AI 技术应用','2','book_type',NULL,'success','N','0','admin','2026-08-21 09:12:06','',NULL,NULL),(102,3,'AI 硬件与场景','3','book_type',NULL,'warning','N','0','admin','2026-08-21 09:12:06','',NULL,NULL),(103,1,'个人主理人','1','reader_type',NULL,'primary','N','0','admin','2026-08-21 09:12:06','',NULL,NULL),(104,2,'团队','2','reader_type',NULL,'success','N','0','admin','2026-08-21 09:12:06','',NULL,NULL),(105,3,'企业','3','reader_type',NULL,'warning','N','0','admin','2026-08-21 09:12:06','',NULL,NULL);
